update public.tips set status = 'retired' where id = '36795a47-81e7-5de0-bfd5-f8dfc8084e28' and status = 'published';
delete from public.lesson_slots where tip_id = '36795a47-81e7-5de0-bfd5-f8dfc8084e28';
update public.tips set body_md = 'The *I* form ends in **-o**: **hablo**, **entiendo**. The vos form is stressed on the end: **hablás**, **entendés**, **repetís**. One verb is different: *I know* is just **sé**, and the vos form is **sabés**. **Me** (*me*) and **te** (*you*) go before the verb: *No te entiendo. ¿Me entendés?* *No entiendo. ¿Hablás inglés?* — *No sé.*' where id = '3ddb4cb9-dbfd-5829-b717-aec8064fbb90' and body_md = 'The *I* form ends in **-o**: **hablo**, **entiendo**. The vos form is stressed on the end: **hablás**, **entendés**, **repetís**. One verb is different: *I know* is just **sé**, and the vos form is **sabés**. *No entiendo. ¿Hablás inglés?* — *No sé.*';
update public.tips set body_md = '**No entendí** — *I didn''t understand* — is what you say when you missed something just said: *Perdón, no entendí.* It is the past of *no entiendo*. For another person, *knows* is **sabe**: *Juan sabe un poco de inglés.*', title_en = 'Entendí, sabe' where id = '95b906a1-cab6-5656-9bd4-7597c0a6238b' and body_md = '**No entendí** — *I didn''t understand* — is what you say when you missed something just said: *Perdón, no entendí. ¿Me repetís?* It is the past of *no entiendo*. Add *más despacio, por favor* and people slow down.';
update public.tips set body_md = 'Spanish has no *''s*. Say the thing, then **de**, then the person: *Juan''s teacher* is **profe de Juan**, *Marta''s student* is **estudiante de Marta**. **De** also comes after *un poco*: *un poco de inglés* — *a little English*.', title_en = 'De' where id = '8f1d1346-2aba-5b40-a0f6-366a54fd2257' and body_md = 'At any counter in Buenos Aires you''ll hear *nombre y apellido, por favor* — your first name and your surname.';
update public.tips set body_md = '*Tener* — to have — is how you give your age: Spanish *has* years.
| yo | **tengo** | Tengo veinte años. |
| vos | **tenés** | ¿Cuántos años tenés? |
| él, ella | **tiene** | Tiene doce años. |
The *e* of *tener* becomes *ie* in *tiene* — but never in the vos form: **tenés**. Before a noun, *uno* is **un**: *tiene un año*.

16 to 19 are **dieci** + the number: *dieciséis*, *diecisiete*, *dieciocho*, *diecinueve*.' where id = '0f6658b9-f4e9-5a1d-836b-ec6f489940ff' and body_md = '*Tener* — to have — is how you give your age: Spanish *has* years.
| yo | **tengo** | Tengo veinte años. |
| vos | **tenés** | ¿Cuántos años tenés? |
| él, ella | **tiene** | Tiene doce años. |
The *e* of *tener* becomes *ie* in *tiene* — but never in the vos form: **tenés**. Before a noun, *uno* is **un**: *tiene un año*.';
update public.tips set body_md = 'From 21 to 29 the number is one word: **veintiuno**, **veintidós**, **veinticinco**. From **treinta** on it is three words joined by **y**: *Tengo treinta y cuatro años.* The same pattern works for **cuarenta**, **cincuenta** and all the way up to **noventa**. Before *años*, **uno** becomes **un**: *veintiún años*, *treinta y un años*.' where id = '0a165b34-8a68-50c2-973b-ae40dc128454' and body_md = 'From 21 to 29 the number is one word: **veintiuno**, **veintidós**, **veinticinco**. From **treinta** on it is three words joined by **y**: *Tengo treinta y cuatro años.* The same pattern works for **cuarenta**, **cincuenta** and all the way up to **noventa**.';
update public.tips set body_md = 'Argentine prices run into the thousands, so you will say **mil** all day. One thousand is just **mil** — never *un mil* — and the word does not change: *Sale mil pesos.* *¿Mil pesos? Es caro.* **Caro** and **barato** end in **-a** for a *la* word: *una gaseosa no es cara*. **¡Qué caro!** — *How expensive!*' where id = 'b29680d4-b383-5aa7-a81f-ac7b3e1b8450' and body_md = 'Argentine prices run into the thousands, so you will say **mil** all day. One thousand is just **mil** — never *un mil* — and the word does not change: *Sale mil pesos.* *¿Mil pesos? Es caro.*';
update public.tips set body_md = '**¿Cuánto sale?** is the everyday Argentine way to ask a price — *¿cuánto cuesta?* works too. Several things **salen** or **cuestan**: *¿cuánto salen las zapatillas?* *To pay* and *to buy* follow one pattern: **pago**, **pagás**, **paga** and **compro**, **comprás**, **compra**. *¿Pagás vos o pago yo?* At the register: *¿tarjeta o efectivo?* — *card or cash?* **Mangos** is slang for pesos: *no tengo un mango* means *I don''t have a peso*.', title_en = 'Pago, pagás, paga' where id = 'fe95866f-3747-5f76-84e6-70b1453b221c' and body_md = '**¿Cuánto sale?** is the everyday Argentine way to ask a price — *¿cuánto cuesta?* works too. One thing **cuesta**, several **cuestan**: *las zapatillas cuestan doscientos mil*. Same with *sale*: several things **salen** — *¿cuánto salen las zapatillas?* **Mangos** is slang for pesos.';
update public.tips set body_md = 'Going somewhere takes **a** — *to* — every time: *Voy a la plaza.* The question word has that **a** built in: **¿adónde vas?** is *where are you going to?* English often drops the *to*; Spanish never drops the **a**. **A + el** becomes **al**: *voy al kiosco*, but *vas a la estación*.' where id = '29afb672-4c8b-59dd-85ee-eef456a2127a' and body_md = 'Going somewhere takes **a** — *to* — every time: *Voy a la plaza.* The question word has that **a** built in: **¿adónde vas?** is *where are you going to?* English often drops the *to*; Spanish never drops the **a**.';
update public.tips set body_md = '*Es la una* (one o''clock), but *son las dos*, *son las siete*. Add **y media** for half past and **y cuarto** for quarter past. Other minutes go the same way: *las siete y veinte*. Past the half hour people often drop the **y**: *las ocho cuarenta*. To ask: *¿Qué hora es?* or *¿Tenés hora?* *At* a time is **a las**: *¿A qué hora?* — *A las nueve y media.* After a clock time say **de la mañana / de la tarde / de la noche**: *a las dos de la tarde*. With no clock time: **a la mañana**, *a la tarde*, *a la noche*.' where id = '97b6abce-e595-58cb-a895-30319da57ada' and body_md = '*Es la una* (one o''clock), but *son las dos*, *son las siete*. Add **y media** for half past and **y cuarto** for quarter past. Other minutes go the same way: *las siete y veinte*. To ask: *¿Qué hora es?* or *¿Tenés hora?* *At* a time is **a las**: *¿A qué hora?* — *A las nueve y media.* After a clock time say **de la mañana / de la tarde / de la noche**: *a las dos de la tarde*. With no clock time: **a la mañana**, *a la tarde*, *a la noche*.';
update public.tips set body_md = 'Days take **el** for one day and **los** for every week: *el miércoles laburo* (on Wednesday), *los lunes laburo* (on Mondays). They have no capital letter. Dates work the same way, with a plain number: *el veintiuno tengo examen*. **Nos vemos** is *see you*; as a question it makes a plan: *¿Nos vemos el sábado?* — *Should we meet on Saturday?*' where id = 'afc27211-febc-5355-9843-5cd952ec9052' and body_md = 'Days take **el** for one day and **los** for every week: *el miércoles laburo* (on Wednesday), *los lunes laburo* (on Mondays). They have no capital letter. Dates work the same way, with a plain number: *el veintiuno tengo examen*.';
update public.tips set body_md = '| | querer | poder | ir |
| yo | quiero | puedo | voy |
| vos | **querés** | **podés** | vas |
| él, ella | quiere | puede | va |
| nosotros | **queremos** | **podemos** | vamos |
| ellos, ustedes | quieren | pueden | van |

*e → ie* and *o → ue* everywhere except **vos** and **nosotros**. *Ir* is its own thing, and takes **a** + place (*a + el* = **al**): *voy al súper*, *voy a la facu*. **Salir** only bends in *yo*: **salgo**, *salís*, *sale*. Add an infinitive for plans: *¿Querés salir?*', title_en = 'Querer, poder, ir' where id = '78286e2b-e254-5636-a5a8-883bdf68f891' and body_md = '| | querer | poder | ir |
| yo | quiero | puedo | voy |
| vos | **querés** | **podés** | vas |
| él, ella | quiere | puede | va |
| nosotros | **queremos** | **podemos** | vamos |
| ellos, ustedes | quieren | pueden | van |

*e → ie* and *o → ue* everywhere except **vos** and **nosotros**. *Ir* is its own thing, and takes **a** + place (*a + el* = **al**): *voy al súper*, *voy a la facu*. **Salir** only bends in *yo*: **salgo**, *salís*, *sale*. Add an infinitive for plans: *¿Querés salir?*';
update public.tips set body_md = 'The future is **ir a** + verb: **voy a laburar**, **vamos a comer**. For a fixed plan the plain present works too: **viajamos el viernes**. *Viajamos* is also *we traveled*: the time word tells you which. **Que viene** after a time word is *next*: **la semana que viene**, **el año que viene**, **el finde que viene**.' where id = 'a5a666cc-13f5-582b-a31d-e3454f6aea44' and body_md = 'Porteños talk about the future with **ir a**: **voy a laburar**, **vamos a comer**. For a fixed plan the plain present works too: **viajamos el viernes**. *Viajamos* is also *we traveled*: the time word tells you which. *Next week* is **la semana que viene**, *next year* **el año que viene**.';
update public.tips set body_md = '**El próximo viernes** is *next Friday* — the same as *el viernes que viene*; **el próximo finde** is *next weekend*. **La próxima** alone is *next time*: *La próxima invito yo.* **La semana que viene** — *next week*, the week that comes — is the form you will hear most.', title_en = 'El próximo, la próxima' where id = '54719e83-d9d7-5d73-98e3-8ba760627cc8' and body_md = '**La semana que viene** is *next week* — the week that comes. Same with days: *el viernes que viene*. **El próximo viernes** means the same. **La próxima** alone is *next time*: *La próxima invito yo.*';
update public.tips set body_md = 'English *bring* is two verbs here. **Llevar** is to a place where you are not yet: *¿Qué llevo al asado?* **Traer** is to the place where you are now: *¿Podés traer hielo?* Going to a friend''s place, always ask **¿qué llevo?** **Venir** works like *traer*: on your way to someone, say **ya voy**, not *vengo*.' where id = 'd5a4acc0-9d64-5970-8f68-5d4ed9936d96' and body_md = 'English *bring* is two verbs here. **Llevar** is to a place where you are not yet: *¿Qué llevo al asado?* **Traer** is to the place where you are now: *¿Podés traer hielo?* Going to a friend''s place, always ask **¿qué llevo?**';
update public.tips set body_md = 'Like *vengo* and *traigo*, these verbs have an odd *I* form: **digo**, **pongo** and **veo**. With vos they are regular: **decís**, **ponés**, **ves**. *Decir* also changes **e** to **i** in **dice** and **dicen**. *—¿Qué decís? —Yo no digo nada.* To tell someone, add **le**: *¿Qué le digo a Ana?*' where id = 'ba82ffe4-0152-5484-bf4b-85a5828f972a' and body_md = 'Like *vengo* and *traigo*, these verbs have an odd *I* form: **digo**, **pongo** and **veo**. With vos they are regular: **decís**, **ponés**, **ves**. *Decir* also changes **e** to **i** in **dice** and **dicen**. *¿Qué decís? — Yo no digo nada.*';
update public.tips set body_md = '**Saber** + a verb is *to know how to*: *Nico sabe cocinar* — *Nico knows how to cook*. For *we* the form is **sabemos**: *Tranqui, sabemos llegar* — *relax, we know how to get there*.', title_en = 'Saber + verb' where id = '46adada6-619f-5734-bbc8-3bc0ff3ab06b' and body_md = '**Saber** + a verb is *to know how to*: **¿sabés cocinar?** For people and places use **conocer**: **conozco a Juan**, **¿conocés Palermo?** And **qué sé yo** is the porteño shrug — *who knows*.';
update public.tips set body_md = '**Ni idea** — *no idea* — is the everyday short answer when you don''t know: *—¿Dónde está Nico? —Ni idea.* The full form is **no tengo idea** or **no tengo ni idea**. To say what about: *Ni idea de dónde está el cargador.*', title_en = 'Ni idea' where id = 'c585fa33-b562-55de-93f1-7f619cc3b533' and body_md = '**Sé** — *I know* — has an accent to tell it from *se*. **¿Sabés qué?** — *you know what?* — opens every piece of gossip.';
update public.tips set body_md = 'The city is **la Capital** — often with no article: *vivo en Capital*. The ring of towns around it is **el conurbano**. Palermo, **San Telmo** and **La Boca** are barrios of the Capital: *Palermo está lleno de bares*, *La Boca es re turística*. The first question to any porteño: **¿en qué barrio vivís?**', title_en = 'Capital y conurbano' where id = '9b2c23e3-838a-574f-affd-f711c01a05fe' and body_md = 'The city is **la Capital** — often with no article: *vivo en Capital*. The ring of towns around it is **el conurbano**. Palermo, **San Telmo** and **La Boca** are barrios of the Capital: *Palermo está lleno de bares*, *La Boca es re turística*. The first question to any porteño: **¿en qué barrio vivís?**';
update public.tips set body_md = '**Celeste** is the light blue of the flag — for porteños a different color from *azul*: *No son azules, son celestes.* **Rosa** and **naranja** keep the *-a* for masculine too: *un pantalón rosa*, *un jean naranja*.' where id = '53370f9c-ba05-5f62-b511-24a2a447f934' and body_md = '**Celeste** is the light blue of the flag — for porteños a different color from *azul*: *No son azules, son celestes.* **Rosa** and **naranja** keep the *-a* for masculine too: *un pantalón rosa*, *una campera naranja*.';
update public.tips set body_md = 'The adjective copies its noun: *una campera nueva*, *un jean nuevo*, *los pantalones chicos*. **Grande** has one form for both: *una remera grande*, *las zapatillas grandes*. Adjectives usually come after the noun, not before as in English. With *¡Qué…!* both orders work: *¡Qué linda remera!*, *¡Qué campera fea!*' where id = '5f0726c3-0c2e-524a-b89f-9832deab7142' and body_md = 'The adjective copies its noun: *una campera nueva*, *un jean nuevo*, *los pantalones chicos*. **Grande** has one form for both: *una remera grande*, *las zapatillas grandes*. And it comes after the noun, not before as in English.';
update public.tips set body_md = 'On a sign, **se** + verb says what is sold, rented or needed, with nobody named: **se vende** auto, **se alquila** depto, **se necesita** mozo. For more than one thing, add **n**: **se venden** bicis. The same **se** asks about rules: **¿se puede fumar acá?** — *can you smoke here?*', title_en = 'Se + verb on a sign' where id = 'a13868ae-2900-572c-98a0-bf4c01691f94' and body_md = '| one thing | more than one |
| **Se vende** auto. | **Se venden** bicis. |
| **Se alquila** depto. | **Se alquilan** deptos. |
| **Se necesita** mozo. | **Se necesitan** mozos. |

**Se** + the *él* form, or the *ellos* form for plurals. Nobody is named: it''s what''s being sold, rented, needed.';
update public.tips set body_md = 'Life''s big steps take the pronoun, like **se casó**: **me recibí** — *I graduated*; mi hermano **se recibió** de abogado; mi tía **se jubiló** — *retired*. Ask **¿de qué te recibiste?** — *what did you graduate in?* **Se murió** — *died* — is for talking among friends; to the family you say **falleció** — *passed away*.', title_en = 'Se recibió, se jubiló' where id = '164a4c51-f39c-5285-b76f-97464dab857a' and body_md = '| Mi hermano **se recibió** de abogado. | graduated |
| **Me recibí** el año pasado. | I graduated |
| **Se comprometieron** en marzo. | they got engaged |
| Mi tía **se jubiló**. | retired |
| Mi abuelo **se murió** en mayo. | died |

Life''s big steps take the pronoun, like **se casó**: *me*, *se*, always in front. Ask **¿de qué te recibiste?** — *what did you graduate in?* And **se murió** is for talking among friends; to the family you say **falleció** — *passed away*.';
update public.tips set body_md = '| Mi prima **se casó** el sábado. | got married |
| **Nos casamos** en marzo. | we got married |
| El bebé **nació** ayer. | was born |
| ¿Dónde **naciste**? | were you born |

**Casarse** takes its pronoun; **nacer** doesn''t. **Nos casamos** is also the present: *nos casamos en julio* — *we''re getting married in July*. The wedding is a **casamiento**; the legal one is **por civil**, or just **el civil**. Before it, **se comprometieron** — *they got engaged*; after it, the **luna de miel**. **Está embarazada** is *she''s pregnant*.' where id = '28e641b6-4f66-5483-81c2-859687fb0e7f' and body_md = '| Mi prima **se casó** el sábado. | got married |
| **Nos casamos** en marzo. | we got married |
| El bebé **nació** ayer. | was born |
| ¿Dónde **naciste**? | were you born |

**Casarse** takes its pronoun; **nacer** doesn''t. **Nos casamos** is also the present: *nos casamos en julio* — *we''re getting married in July*. The wedding is a **casamiento**, and **está embarazada** is *she''s pregnant*.';
update public.tips set body_md = '**Capaz**, **a lo mejor** and **quizás** all mean *maybe*; **seguro que** is *I bet*; **supongo que** is *I guess*; **probablemente** is *probably*. All take the plain present: **capaz está en la plaza**, **seguro que es Fede**. In Buenos Aires you will hear **capaz** much more than **quizás**.' where id = '6f3c143b-2af0-5c70-b9e2-7435c2b347d4' and body_md = '**Capaz**, **a lo mejor** and **quizás** all mean *maybe*; **seguro que** is *I bet*; **supongo que** is *I guess*. All take the plain present: **capaz está en la plaza**, **seguro que es Fede**. In Buenos Aires you will hear **capaz** much more than **quizás**.';
update public.tips set body_md = '**Qué pesado** — *what a pain* — for someone who won''t let it go. **Divertido** is *fun*, **tímido** *shy*. For a woman: **pesada**, **divertida**, **tímida**. With **estar** it is just for now: *Nico está pesado hoy* — *Nico''s being annoying today*.' where id = '6f623f96-84dd-5f21-953b-3e2e7b40775a' and body_md = '**Qué pesado** — *what a pain* — for someone who won''t let it go. **Divertido** is *fun*, **tímido** *shy*.';
update public.tips set body_md = '**Ya no** is *not anymore*: **ya no vivo ahí**. Porteños say it even more with **no … más**: *no vivo más ahí*. The opposite is **sigue** — *still*: *sigue roto*, *sigue lloviendo*. **Cada vez más** — *more and more*: *cada vez más caro*; **cada vez menos** — *less and less*.', title_en = 'Ya no, sigue' where id = '29090f79-278c-5890-bf3e-c89cc7947b4a' and body_md = '**Ya no** is *not anymore*: **ya no vivo ahí**. **Cada vez más** — *more and more*: **cada vez más caro**; **cada vez menos** — *less and less*.';
update public.tips set body_md = 'The ATM is **el cajero**: **voy al cajero a sacar plata**. Paying a friend goes by **transferencia** to their **alias** — a few words instead of an account number: **¿a qué alias transferiste?** After it: **¿me mandás el comprobante?** The **sucursal** is the bank branch; a **comisión** is the fee a cajero charges; **las cuentas** are your bills, or your bank accounts.' where id = 'bf96bee5-076e-5167-adb6-ac24c4793a4d' and body_md = 'The ATM is **el cajero**: **voy al cajero a sacar plata**. Paying a friend goes by **transferencia** to their **alias** — a few words instead of an account number: **¿a qué alias transferiste?** After it: **¿me mandás el comprobante?**';
update public.tips set body_md = '**Acabo de** + infinitive is *I just did it*: **acabo de comer**, **acaba de salir**. Porteños mostly say **recién** + the past instead: **recién llegué**, **recién salió** — it means the same. **Volví a** is *I did it again*: **volví a llamar**. Or just **de nuevo** or **otra vez** — *again*.' where id = '043bf160-0648-51c6-bec2-2b7afbcb4c4a' and body_md = '**Acabo de** + infinitive is *I just did it*: **acabo de llegar**, **acaba de salir**. Porteños mostly say **recién** + the past instead: **recién llegué**, **recién salió** — it means the same. **Volví a** is *I did it again*: **volví a perder las llaves**. Or just **de nuevo** or **otra vez** — *again*.';
update public.tips set body_md = '**Lo que** is *what* when it means *the thing that*: **¿viste lo que pasó?**, **contame lo que pasó**. It is how every chisme starts: **no sabés lo que me contaron** — *you won''t believe what they told me*. A direct question keeps **qué**: *¿qué pasó?*' where id = '457aa31e-c947-5f00-b748-3212e6826684' and body_md = '**Lo que** is *what* when it means *the thing that*: **¿viste lo que pasó?**, **contame lo que pasó**. It is how every chisme starts: **no sabés lo que me contaron** — *you won''t believe what I heard*. A direct question keeps **qué**: *¿qué pasó?*';
update public.tips set body_md = '| **Deberías** descansar. | You should rest. |
| **Debería** llamarla. | I should call her. |
| **Estaría bueno** juntarnos. | It''d be nice to get together. |
| **Habría que** avisarle. | We ought to let him know. |

All four can take an infinitive. **Estaría bueno** — the softest porteño suggestion — also takes **que** + subjunctive: *estaría bueno que vengas*. *Tenés que* is stronger — *you have to*; *deberías* is advice.' where id = '4f42bca0-b0c9-54dd-894d-af1e0ddee783' and body_md = '| **Deberías** descansar. | You should rest. |
| **Debería** llamarla. | I should call her. |
| **Estaría bueno** juntarnos. | It''d be nice to get together. |
| **Habría que** avisarle. | We ought to let him know. |

All four can take an infinitive. **Estaría bueno** also takes **que** + subjunctive: *estaría bueno que vengas*. *Tenés que* is stronger — *you have to*; *deberías* is advice.';
update public.tips set body_md = 'Reporting a promise: «voy» → **dijo que iba a venir**; «te llamo» → **dijo que me iba a llamar**. That is what porteños say day to day. In writing and in careful speech the same thing goes into *would*: **dijo que vendría**, **dijo que me llamaría** — learn to recognise it. Even shorter in fast speech: **dijo que me llamaba** — *he said he''d call me*.' where id = '89ceed83-6de5-5102-bf3b-75fb12b34e48' and body_md = 'Reporting a promise: «voy» → **dijo que iba a venir**; «te llamo» → **dijo que me iba a llamar**. That is what porteños say day to day. In writing and in careful speech the same thing goes into *would*: **dijo que vendría**, **dijo que me llamaría** — learn to recognise it.';
update public.tips set body_md = 'These hurt. **Pelotudo** is stronger than *boludo*; only close friends say it as a joke. A **forro** is a nasty person. An **hinchapelotas** won''t stop bothering you: *¡no rompas las bolas!* — often just *¡no rompas!* **Andá a cagar** is *go to hell*: a joke between friends, a fight with a stranger. **Hijo de puta** is one of the strongest insults — but shouted at a great goal it is admiration.' where id = 'da8de45b-718a-598c-b598-e48991bb7640' and body_md = 'These hurt. **Pelotudo** is stronger than *boludo* and rarely friendly. A **forro** is a nasty person. An **hinchapelotas** won''t stop bothering you: *¡no rompas las bolas!* — often just *¡no rompas!* **Andá a cagar** is *get lost*: a joke between friends, a fight with a stranger.';
update public.tips set body_md = 'Most swearing is aimed at the situation, not at a person: **¡la puta madre!**, **¡la concha de la lora!**, **¡mierda!**, **¡carajo!**, **¡qué cagada!** A bad day is *un día de mierda*. **Me chupa un huevo** is *I don''t give a shit*. Two are not insults, just very informal: **una boludez** is something silly or small, and **me cagué de risa** means *I laughed my ass off* — I laughed a lot.' where id = '312fb178-1035-5102-b74c-28c2d9e736b2' and body_md = 'Most swearing is aimed at the situation, not at a person: **¡la puta madre!**, **¡mierda!**, **¡carajo!**, **¡qué cagada!** A bad day is *un día de mierda*. Two are harmless: **una boludez** is something silly or small, and **me cagué de risa** means *I laughed a lot*.';
update public.tips set body_md = 'Election day is a Sunday, and everyone asks **¿dónde votás?** — usually at a school near home: **votamos en la misma escuela**. Your **mesa** is the numbered table where you vote. Before it there is **veda**: campaigning stops 48 hours before the vote, and from the night before nobody can sell alcohol.' where id = '2a3a2462-0e4e-58df-9bc1-fcf6e909f66e' and body_md = 'Election day is a Sunday, and everyone asks **¿dónde votás?** — usually at a school near home: **votamos en la misma escuela**. Before it there is **veda**: campaigning stops 48 hours before the vote, and from the night before nobody can sell alcohol.';
update public.tips set body_md = '**Aparentemente** is the neutral *apparently*: **aparentemente, mañana hay paro**; **por lo visto** means the same. **Se ve que** is what you conclude from what you see: **se ve que llovió** — *it must have rained*; **se ve que está cerrado**.' where id = '6d88948a-49cd-507f-b390-3b282380d755' and body_md = '**Aparentemente** is the neutral *apparently*: **aparentemente, mañana hay paro**. **Se ve que** is what you conclude from what you see: **se ve que llovió** — *it must have rained*; **se ve que está cerrado**.';
update public.tips set body_md = 'Put **lo** before an adjective to say *the … thing*: **lo lindo** — *the nice thing*, **lo feo** — *the bad part* (same as **lo malo**), **lo único** — *the only thing*. Add **de** to say of what: **lo peor de Buenos Aires es el tránsito**. **Lo** never changes: **lo feo son los precios**.' where id = '7ae297c7-20ed-5a6a-976d-9efc0c4c19d4' and body_md = 'Put **lo** before an adjective to say *the … thing*: **lo lindo** — *the nice thing*, **lo feo** — *the bad part*, **lo único** — *the only thing*. Add **de** to say of what: **lo peor de Buenos Aires es el tránsito**. **Lo** never changes: **lo feo son los precios**.';
update public.tips set body_md = 'You will hear these words every day — in traffic, at soccer games, between friends. Learn to understand them first. Say them only with close friends who already swear with you. Never to a stranger, at work, to someone older or to the police.' where id = '884f42b5-2708-5009-ac9c-58b4265070d5' and body_md = 'You will hear these words every day — in traffic, at the football, between friends. Learn to understand them first. Say them only with close friends who already swear with you. Never to a stranger, at work, to someone older or to the police.';
